
SELECT 'analytics.dim_customer_dataco' AS table_name, 'customer_id' AS checked_key, COUNT(*) AS duplicate_groups FROM (SELECT customer_id FROM analytics.dim_customer_dataco GROUP BY customer_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'analytics.dim_customer_dataco', 'customer_key', COUNT(*) FROM (SELECT customer_key FROM analytics.dim_customer_dataco GROUP BY customer_key HAVING COUNT(*) > 1) d UNION ALL SELECT 'analytics.dim_date', 'full_date', COUNT(*) FROM (SELECT full_date FROM analytics.dim_date GROUP BY full_date HAVING COUNT(*) > 1) d UNION ALL SELECT 'analytics.dim_date', 'date_key', COUNT(*) FROM (SELECT date_key FROM analytics.dim_date GROUP BY date_key HAVING COUNT(*) > 1) d UNION ALL SELECT 'analytics.dim_geography', 'geography_key', COUNT(*) FROM (SELECT geography_key FROM analytics.dim_geography GROUP BY geography_key HAVING COUNT(*) > 1) d UNION ALL SELECT 'analytics.dim_product', 'product_key', COUNT(*) FROM (SELECT product_key FROM analytics.dim_product GROUP BY product_key HAVING COUNT(*) > 1) d UNION ALL SELECT 'analytics.dim_product', 'product_id', COUNT(*) FROM (SELECT product_id FROM analytics.dim_product GROUP BY product_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'analytics.fact_order_items', 'order_item_id', COUNT(*) FROM (SELECT order_item_id FROM analytics.fact_order_items GROUP BY order_item_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.customers_dataco', 'customer_id', COUNT(*) FROM (SELECT customer_id FROM core.customers_dataco GROUP BY customer_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.inventory_master', 'inventory_id', COUNT(*) FROM (SELECT inventory_id FROM core.inventory_master GROUP BY inventory_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.inventory_master', 'product_id', COUNT(*) FROM (SELECT product_id FROM core.inventory_master GROUP BY product_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.inventory_snapshots', 'inventory_id + snapshot_date', COUNT(*) FROM (SELECT inventory_id, snapshot_date FROM core.inventory_snapshots GROUP BY inventory_id, snapshot_date HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.inventory_snapshots', 'snapshot_id', COUNT(*) FROM (SELECT snapshot_id FROM core.inventory_snapshots GROUP BY snapshot_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.olist_customers', 'customer_id', COUNT(*) FROM (SELECT customer_id FROM core.olist_customers GROUP BY customer_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.order_items', 'order_item_id', COUNT(*) FROM (SELECT order_item_id FROM core.order_items GROUP BY order_item_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.orders', 'order_id', COUNT(*) FROM (SELECT order_id FROM core.orders GROUP BY order_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.product_suppliers', 'product_supplier_id', COUNT(*) FROM (SELECT product_supplier_id FROM core.product_suppliers GROUP BY product_supplier_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.product_suppliers', 'product_id + supplier_id', COUNT(*) FROM (SELECT product_id, supplier_id FROM core.product_suppliers GROUP BY product_id, supplier_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.products', 'product_id', COUNT(*) FROM (SELECT product_id FROM core.products GROUP BY product_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.supplier_performance', 'performance_id', COUNT(*) FROM (SELECT performance_id FROM core.supplier_performance GROUP BY performance_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.supplier_performance', 'purchase_order_code', COUNT(*) FROM (SELECT purchase_order_code FROM core.supplier_performance GROUP BY purchase_order_code HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.suppliers', 'supplier_id', COUNT(*) FROM (SELECT supplier_id FROM core.suppliers GROUP BY supplier_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'core.suppliers', 'supplier_code', COUNT(*) FROM (SELECT supplier_code FROM core.suppliers GROUP BY supplier_code HAVING COUNT(*) > 1) d UNION ALL SELECT 'staging.dataco_raw', 'source_row_id', COUNT(*) FROM (SELECT source_row_id FROM staging.dataco_raw GROUP BY source_row_id HAVING COUNT(*) > 1) d UNION ALL SELECT 'staging.olist_customers_raw', 'source_row_id', COUNT(*) FROM (SELECT source_row_id FROM staging.olist_customers_raw GROUP BY source_row_id HAVING COUNT(*) > 1) d ORDER BY table_name, checked_key;

